'use strict';

// Opt-in integration probe: node tests/run-aria2-local-transfer.js <aria2.exe> [test-parent]
// Serves generated bytes on loopback; never contacts a file host or opens user downloads.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const http = require('node:http');
const vm = require('node:vm');
const crypto = require('node:crypto');
const { spawn, execFileSync } = require('node:child_process');
const DownloadSizeLogic = require('../ui/downloadSizeLogic');

async function main() {
    assert.ok(process.argv[2], 'Pass the installed aria2 executable path');
    const binary = fs.realpathSync(process.argv[2]);
    const parent = fs.realpathSync(process.argv[3] || os.tmpdir());
    const dir = fs.mkdtempSync(path.join(parent, 'sail-aria2-test-'));
    const source = fs.readFileSync(path.join(__dirname, '..', 'main.js'), 'utf8');
    const start = source.indexOf('function runAria2Download(');
    const end = source.indexOf('function browserBytes(', start);
    assert.ok(start >= 0 && end > start);
    const run = vm.runInNewContext(`(${source.slice(start, end)})`, {
        spawn, setTimeout, clearTimeout, console, DownloadSizeLogic,
        safeOutName: name => name, DL_UA: 'Sail-Local-Transfer-Test'
    });
    const total = 128 * 1024 * 1024;
    const chunkSize = 64 * 1024;
    function payload(position, length) {
        const bytes = Buffer.allocUnsafe(length);
        for (let i = 0; i < length; i++) {
            const offset = position + i;
            bytes[i] = (offset * 31 + Math.floor(offset / chunkSize)) & 255;
        }
        return bytes;
    }
    let sent = 0;
    const sockets = new Set();
    const server = http.createServer((req, res) => {
        const match = /^bytes=(\d+)-(\d*)$/.exec(req.headers.range || '');
        let position = match ? Number(match[1]) : 0;
        const last = match && match[2] ? Number(match[2]) : total - 1;
        if (position > last || last >= total) { res.writeHead(416).end(); return; }
        res.writeHead(match ? 206 : 200, {
            'Content-Length': last - position + 1, 'Accept-Ranges': 'bytes',
            ...(match ? { 'Content-Range': `bytes ${position}-${last}/${total}` } : {})
        });
        let blocked = false;
        res.on('drain', () => { blocked = false; });
        const timer = setInterval(() => {
            if (blocked) return;
            if (position > last) { clearInterval(timer); res.end(); return; }
            const length = Math.min(chunkSize, last - position + 1);
            blocked = !res.write(payload(position, length));
            position += length;
            sent += length;
        }, 100);
        res.on('close', () => clearInterval(timer));
    });
    server.on('connection', socket => {
        sockets.add(socket);
        socket.on('close', () => sockets.delete(socket));
    });
    const ctl = {};
    let deadline;
    try {
        await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
        const file = { url: `http://127.0.0.1:${server.address().port}/fixture.bin`, name: 'fixture.bin' };
        const events = [];
        let pauseStarted = 0;
        deadline = setTimeout(() => { ctl.cancelled = true; if (ctl.proc) ctl.proc.kill(); }, 60000);
        await assert.rejects(run(binary, file, dir, {}, ctl, event => {
            if (event.phase !== 'downloading') return;
            events.push(event);
            if (!ctl.paused && DownloadSizeLogic.downloadSizeBytes(event.downloaded) >= 40 * 1024 * 1024) {
                ctl.paused = true;
                pauseStarted = Date.now();
                ctl.proc.kill();
            }
        }), /Paused/);
        const pauseMs = Date.now() - pauseStarted;
        assert.ok(pauseStarted && pauseMs < 5000, `Pause took ${pauseMs}ms`);
        assert.ok(events.length >= 2 && events.at(-1).percent > events[0].percent);
        const output = path.join(dir, 'fixture.bin');
        const logicalBytes = fs.statSync(output).size;
        assert.ok(sent < total, 'Partial fixture must not have finished');
        let allocatedBytes;
        if (process.platform === 'win32') {
            // NTFS integration check: unwritten segments must remain unallocated.
            const ranges = execFileSync('fsutil.exe', ['file', 'queryallocranges', 'offset=0', `length=${total}`, output], { encoding: 'utf8', windowsHide: true });
            const pairs = [...ranges.matchAll(/0x([\da-f]+)\s+[^\r\n]*?0x([\da-f]+)/gi)];
            assert.ok(pairs.length, 'Expected flushed, allocated ranges');
            allocatedBytes = pairs.reduce((sum, pair) => sum + parseInt(pair[2], 16), 0);
            assert.ok(allocatedBytes < total / 2, `Unwritten gaps allocated: ${allocatedBytes} bytes`);
        }
        assert.equal(logicalBytes, total);
        ctl.paused = false;
        await run(binary, file, dir, {}, ctl, () => {});
        const expected = crypto.createHash('sha256');
        for (let offset = 0; offset < total; offset += chunkSize) expected.update(payload(offset, chunkSize));
        const actual = crypto.createHash('sha256');
        for await (const bytes of fs.createReadStream(output)) actual.update(bytes);
        assert.equal(actual.digest('hex'), expected.digest('hex'), 'Resumed payload must contain every expected byte');
        console.log(JSON.stringify({ passed: true, progressEvents: events.length, pauseMs, logicalBytes, allocatedBytes, resumedHashMatches: true }));
    } finally {
        clearTimeout(deadline);
        if (ctl.proc) {
            await new Promise(resolve => { ctl.proc.once('close', resolve); ctl.proc.kill(); });
        }
        for (const socket of sockets) socket.destroy();
        await new Promise(resolve => server.close(resolve));
        const resolved = fs.realpathSync(dir);
        assert.equal(path.dirname(resolved), parent);
        assert.ok(path.basename(resolved).startsWith('sail-aria2-test-'));
        fs.rmSync(resolved, { recursive: true, force: true });
    }
}

main().catch(error => { console.error(error); process.exitCode = 1; });
